import {modules,lessonCount} from './content.js';
const root=document.querySelector('#app');
const initial=()=>({done:[],xp:0,days:[],notes:[],missed:[]});
let state=initial();try{const s=JSON.parse(localStorage.getItem('curd-v1'));if(s&&Array.isArray(s.done)&&Array.isArray(s.notes)&&Array.isArray(s.days)&&Array.isArray(s.missed)&&Number.isFinite(s.xp))state=s;}catch{}
let view='learn',activeModule=0,session=null,notice='';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function save(){try{localStorage.setItem('curd-v1',JSON.stringify(state));}catch{notice='Storage is unavailable. Your progress will last only for this visit.';}}
function streak(){let d=new Date();let count=0;if(!state.days.includes(today()))d.setDate(d.getDate()-1);while(state.days.includes(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`)){count++;d.setDate(d.getDate()-1);}return count;}
const paths={learn:'M5 5h6v15H5zM13 5h6v15h-6',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',cheese:'M3 10 15 3l6 7v11H3zM3 10h18M8 14h.1M15 17h.1',milk:'M8 3h8v5l3 4v9H5v-9l3-4zM8 7h8M5 13h14',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',box:'m3 7 9-4 9 4v13H3zM3 7l9 5 9-5M12 12v8',chat:'M3 4h18v13H9l-6 4z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c-6 6-6 14 0 20 6-6 6-14 0-20',shield:'m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7z',journal:'M5 3h14v18H5zM8 8h8M8 12h8M8 16h5',check:'m5 12 5 5L20 7',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5z',arrow:'M5 12h14m-5-5 5 5-5 5',fire:'M12 2c3 5-2 6 3 10 2-1 3-3 3-3 7 10-2 15-8 12C1 18 5 11 8 8c-1 5 4 5 4-6'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.star}"/></svg>`;
const mascot=`<svg class="mascot" viewBox="0 0 240 210" aria-hidden="true"><ellipse cx="121" cy="188" rx="65" ry="8" fill="#e7e0c8"/><path d="M49 78 155 35l48 49v79c-37 18-101 22-154 0Z" fill="#f0c85e" stroke="#55482d" stroke-width="3"/><path d="M49 78c41 11 99 12 154 6l-48-49Z" fill="#ffe69b" stroke="#55482d" stroke-width="3"/><path d="M49 78v85c48 17 109 18 154 0V84" fill="none" stroke="#55482d" stroke-width="3"/><ellipse cx="88" cy="68" rx="12" ry="5" fill="#d3a83e"/><ellipse cx="145" cy="62" rx="9" ry="5" fill="#d3a83e"/><circle cx="71" cy="111" r="8" fill="#dcb148"/><circle cx="181" cy="147" r="10" fill="#dcb148"/><circle cx="83" cy="153" r="5" fill="#dcb148"/><path d="M108 113v8m39-8v8m-33 15q12 13 25-1" stroke="#55482d" stroke-width="5" stroke-linecap="round" fill="none"/><path d="m51 129-20-13m172 6 17-19M90 175l-4 13m69-13 4 13" stroke="#55482d" stroke-width="4" stroke-linecap="round"/><path d="m29 105 2 11-11-1m197-23 3 11 10-4" fill="none" stroke="#55482d" stroke-width="3" stroke-linecap="round"/></svg>`;
function nav(){return [['learn','Learn','learn'],['practice','Practice','star'],['journal','Tasting journal','journal']].map(([v,t,i])=>`<button class="nav-item ${view===v?'active':''}" data-view="${v}">${icon(i)}<span>${t}</span></button>`).join('');}
function render(){if(session){renderLesson();return;}root.innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Curd home">${icon('cheese')}curd</a><div class="brand-note">A LITTLE KNOWLEDGE. DAILY.</div><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><span class="level-mark">01</span><div>Cheese curious<br><small>Your first chapter starts here.</small></div></div></aside><div class="shell"><header><span>YOUR DAILY CHEESE SCHOOL</span><div class="stats"><span title="Consecutive study days">${icon('fire')} ${streak()} <small>day streak</small></span><span>${icon('star')} ${state.xp} <small>XP</small></span><div class="avatar">C</div></div></header><main>${notice?`<p role="status">${esc(notice)}</p>`:''}${view==='learn'?learn():view==='practice'?practice():journal()}</main><footer>Made for the love of cheese. <a href="https://academyofcheese.org/study-cheese/associate/" target="_blank" rel="noreferrer">Course inspiration ↗</a><span>Independent study aid · Unofficial practice content</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav()}</nav>`;bind();}
function learn(){const m=modules[activeModule];let done=m.lessons.filter((_,i)=>state.done.includes(`${activeModule}-${i}`)).length;return `<div class="page-title"><div><div class="eyebrow">THE LEARNING PATH</div><h1>Big cheese energy.<br>A little every day.</h1><p>Build your cheese knowledge, one delicious discovery at a time.</p></div><span class="edition">THE<br>CHEESE<br>CURIOUS<br><b>CLUB / 01</b></span></div><div class="dashboard"><section><div class="chapter"><div><span class="eyebrow">CHAPTER ${String(activeModule+1).padStart(2,'0')} <span class="dot">·</span> FOUNDATIONS</span><h2>${m.title}</h2><p>${m.intro}</p><span class="chapter-count">${done} / ${m.lessons.length||'—'} lessons complete</span></div>${mascot}</div><div class="lesson-heading"><h3>Your next little discovery</h3><span>${m.lessons.length?'3–5 MIN / LESSON':'COMING NEXT'}</span></div><div class="lessons">${m.lessons.length?m.lessons.map((l,i)=>{let completed=state.done.includes(`${activeModule}-${i}`);let locked=i>0&&!state.done.includes(`${activeModule}-${i-1}`);return `<button class="lesson-row ${completed?'completed':''} ${locked?'locked':''}" data-lesson="${activeModule}-${i}" ${locked?'disabled':''}><span class="lesson-node">${icon(completed?'check':locked?'lock':i===0?'milk':'cheese')}</span><span class="lesson-info"><small>LESSON ${i+1}${completed?' · COMPLETE':''}</small><strong>${l.title}</strong><span>${completed?'A little knowledge, well earned.':locked?'Complete the lesson above to unlock':'A quick read. Three questions. One step closer.'}</span></span><span class="lesson-tail">${completed?'REVISIT':locked?'':`START ${icon('arrow')}`}</span></button>`}).join(''):`<div class="empty"><h3>This chapter is still ripening.</h3><p>The curriculum map is here. More original lessons are on the way.</p><button class="primary" data-module="0">Explore the foundations</button></div>`}</div><div class="course-heading"><h3>The bigger picture</h3><span>9 SUBJECT AREAS</span></div><div class="module-list">${modules.map((v,i)=>`<button data-module="${i}" class="module ${i===activeModule?'selected':''}"><span class="module-number">${String(i+1).padStart(2,'0')}</span><span>${v.topic}<small>${v.lessons.length?`${v.lessons.length} lessons ready`:'In development'}</small></span>${i===activeModule?'<span class="current-dot"></span>':icon('arrow')}</button>`).join('')}</div></section><aside class="right-rail"><div class="daily"><span class="eyebrow">SMALL STEPS, GOOD HABITS</span><h3>Your daily slice</h3><div class="goal-ring"><span>${state.days.includes(today())?'1':'0'}<small>/ 1 lesson</small></span></div><p>${state.days.includes(today())?'Today’s goal, beautifully done.':'A few minutes today. A little more confidence tomorrow.'}</p><div class="goal-bottom">${icon('star')} Finish a lesson to reach your goal</div></div><div class="tasting-prompt"><span class="eyebrow">OFF-SCREEN LEARNING</span>${icon('cheese','large-icon')}<h3>Good taste takes practice.</h3><p>Have a cheese in front of you? Capture what you see, smell and taste.</p><button class="text-button" data-view="journal">Open your tasting journal ${icon('arrow')}</button></div><div class="progress-note"><b>${state.done.length} of ${lessonCount}</b> available lessons completed<div class="progress-track"><i style="width:${state.done.length/lessonCount*100}%"></i></div><p>Your progress is saved on this device.</p></div></aside></div>`;}
function practice(){const list=state.missed.map(k=>{const [m,l,q]=k.split('-').map(Number);return {key:k,q:modules[m]?.lessons[l]?.questions[q]};}).filter(v=>v.q);return `<div class="eyebrow">MAKE IT STICK</div><h1>A second helping.</h1><p>Revisit tricky questions, or refresh a lesson you already know.</p><div class="practice-banner">${icon('star','large-icon')}<div><h2>${list.length?`${list.length} questions to revisit`:'A fresh start for your memory'}</h2><p>${list.length?'Mistakes are useful. Give these another try.':'Questions you miss in lessons will appear here.'}</p></div>${list.length?'<button class="primary" id="review">Practice mistakes</button>':''}</div><div class="module-list">${modules.flatMap((m,mi)=>m.lessons.map((l,li)=>`<button class="module" data-lesson="${mi}-${li}">${icon('learn')}<span>${l.title}<small>${m.topic}</small></span>${icon('arrow')}</button>`)).join('')}</div>`;}
function journal(){return `<div class="eyebrow">YOUR TASTING NOTEBOOK</div><h1>Remember every bite.</h1><p>No perfect vocabulary needed. Start with what you notice.</p><div class="journal-layout"><form id="note-form"><label>Cheese name<input name="cheese" placeholder="e.g. A mature farmhouse Cheddar" maxlength="120" required></label><div class="form-row"><label>Milk<select name="milk"><option>Not sure yet</option>Cow</option>Goat</option>Sheep</option>Buffalo</option>Mixed</option></select></label><label>Tasted on<input name="date" type="date" value="${today()}" required></label></div><label>Look & smell<textarea name="aroma" placeholder="The rind, the colour, that first aroma…" maxlength="1500"></textarea></label><label>Texture & flavour<textarea name="flavour" placeholder="Creamy, crumbly, nutty, tangy? Your words belong here." maxlength="1500" required></textarea></label><label>Your enjoyment<select name="rating"><option value="5">5 / 5 — Would absolutely taste again</option><option value="4">4 / 5 — Really enjoyed it</option><option value="3">3 / 5 — Interesting</option><option value="2">2 / 5 — Not quite for me</option><option value="1">1 / 5 — One taste was enough</option></select></label><button class="primary" type="submit">Save tasting note ${icon('arrow')}</button><small class="local-note">Saved in this browser. No account required.</small></form><section class="notes"><h3>Your collection <span>${state.notes.length}</span></h3>${state.notes.length?state.notes.slice().reverse().map(n=>`<article class="note"><span class="eyebrow">${esc(n.date)} · ${esc(n.milk)} MILK</span><h2>${esc(n.cheese)}</h2><span class="rating">${esc(n.rating)} / 5</span><p>${esc(n.aroma)}</p><p>${esc(n.flavour)}</p><button class="text-button delete-note" data-delete="${esc(n.id)}">Delete note</button></article>`).join(''):`<div class="empty">${icon('journal','large-icon')}<h3>Your first taste starts a story.</h3><p>Add a note to begin your own cheese collection.</p></div>`}</section></div>`;}
function bind(){document.querySelector('.brand')?.addEventListener('click',e=>{e.preventDefault();view='learn';render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo(0,0);});document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{activeModule=Number(b.dataset.module);render();window.scrollTo(0,0);});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>start(b.dataset.lesson));document.querySelector('#review')?.addEventListener('click',()=>{session={review:true,questions:state.missed.map(key=>{let [m,l,q]=key.split('-').map(Number);return {key,data:modules[m]?.lessons[l]?.questions[q]};}).filter(q=>q.data),step:0,selected:null,checked:false,correct:0,phase:'quiz'};render();});document.querySelector('#note-form')?.addEventListener('submit',e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));if(!values.cheese.trim()||!values.flavour.trim())return;state.notes.push({...values,id:crypto.randomUUID()});save();notice='Tasting note saved.';render();});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this tasting note?')){state.notes=state.notes.filter(n=>n.id!==b.dataset.delete);save();render();}});}
function start(id){let [mi,li]=id.split('-').map(Number);let lesson=modules[mi].lessons[li];session={id,lesson,questions:lesson.questions.map((data,i)=>({key:`${id}-${i}`,data})),step:0,selected:null,checked:false,correct:0,phase:'read'};render();}
function renderLesson(){const s=session;const q=s.questions[s.step];root.innerHTML=`<div class="lesson-screen"><header class="lesson-header"><button class="close" aria-label="Exit lesson">×</button><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="${s.questions.length}" aria-valuenow="${s.phase==='done'?s.questions.length:s.step}"><i style="width:${s.phase==='done'?100:s.step/s.questions.length*100}%"></i></div><span>${s.phase==='done'?'COMPLETE':s.phase==='read'?'QUICK READ':`${s.step+1} / ${s.questions.length}`}</span></header><main class="lesson-content">${s.phase==='read'?`<span class="eyebrow">A LITTLE KNOWLEDGE FIRST</span><h1>${s.lesson.title}</h1><div class="reading-art">${mascot}</div><p class="reading">${s.lesson.read}</p><p class="read-hint">Take your time. Then try three quick questions.</p><button class="primary" id="begin">Let’s try it ${icon('arrow')}</button>`:s.phase==='done'?`<div class="completion">${mascot}<span class="eyebrow">A LITTLE WISER. A LITTLE CHEESIER.</span><h1>${s.review?'Fresh in your memory.':'That’s a daily slice done.'}</h1><p>You answered ${s.correct} of ${s.questions.length} correctly.</p><div class="completion-stats"><div><b>+${s.reward}</b><span>XP EARNED</span></div><div><b>${streak()}</b><span>DAY STREAK</span></div></div><p>${state.missed.length?'You can revisit missed questions in Practice.':'Nice work. Come back for another little discovery.'}</p><button class="primary" id="finish">Back to learning ${icon('arrow')}</button></div>`:`<span class="eyebrow">${s.review?'A SECOND HELPING':'CHECK YOUR KNOWLEDGE'}</span><h1 class="question">${q.data[0]}</h1><p>Choose one answer.</p><div class="answers">${q.data[1].map((a,i)=>`<button class="answer ${s.selected===i?'selected':''} ${s.checked&&i===q.data[2]?'correct':''} ${s.checked&&s.selected===i&&i!==q.data[2]?'wrong':''}" data-answer="${i}" ${s.checked?'disabled':''} aria-pressed="${s.selected===i}"><span>${String.fromCharCode(65+i)}</span>${a}${s.checked&&i===q.data[2]?icon('check'):''}</button>`).join('')}</div><div class="feedback ${s.checked?(s.selected===q.data[2]?'positive':'negative'):''}" aria-live="polite">${s.checked?`<h3>${s.selected===q.data[2]?'That’s right.':'A useful little discovery.'}</h3><p>${q.data[3]}</p>`:''}</div><button class="primary" id="check" ${s.selected===null?'disabled':''}>${s.checked?s.step===s.questions.length-1?'Finish lesson':'Continue':'Check answer'} ${icon('arrow')}</button>`}</main></div>`;
document.querySelector('.close').onclick=()=>{if(s.phase==='done'||confirm('Leave this lesson? Progress in this attempt will not be saved.')){session=null;render();}};document.querySelector('#begin')?.addEventListener('click',()=>{s.phase='quiz';render();});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{s.selected=Number(b.dataset.answer);render();});document.querySelector('#check')?.addEventListener('click',()=>{if(s.checked){s.step++;s.selected=null;s.checked=false;if(s.step===s.questions.length)complete();render();}else{if(s.selected===null)return;s.checked=true;if(s.selected===q.data[2]){s.correct++;state.missed=state.missed.filter(k=>k!==q.key);}else if(!state.missed.includes(q.key))state.missed.push(q.key);save();render();}});document.querySelector('#finish')?.addEventListener('click',()=>{session=null;view='learn';render();});window.scrollTo(0,0);}
function complete(){const s=session;s.reward=s.review?5:state.done.includes(s.id)?5:20;if(!s.review&&!state.done.includes(s.id))state.done.push(s.id);state.xp+=s.reward;if(!state.days.includes(today()))state.days.push(today());s.phase='done';save();}
render();
